      "slug": "adapt-heat.592",
      "title": "ADAPT-HEAT – Hitzesensible Medikationsanpassung",
      "acronym": "ADAPT-HEAT",
      "url": "https://innovationsfonds.g-ba.de/projekte/adapt-heat.592",
      "summary": "Seit einigen Jahren kommt es immer häufiger zu Hitzewellen, und es ist im Zuge des Klimawandels zu erwarten, dass sich diese Entwicklung fortsetzt.",
      "description": "Seit einigen Jahren kommt es immer häufiger zu Hitzewellen, und es ist im Zuge des Klimawandels zu erwarten, dass sich diese Entwicklung fortsetzt. Extreme Hitzeereignisse können fatale Folgen haben: In den Jahren 2018-2020 wurden laut Robert-Koch-Institut in Deutschland rund 20.000 Todesfälle in Zusammenhang mit Hitze gebracht. Laut wissenschaftlichen Studien scheinen bei Menschen mit chronischen Vorerkrankungen einige Medikamente das hitzebedingte Gesundheitsrisiko zu verstärken.\n\nIm Rahmen des Projekts ADAPT-HEAT wird eine Liste entwickelt, die sogenannte CALOR-Liste, die eine Übersicht über relevante Medikamente und Empfehlungen zur Medikationsanpassung gibt. Dabei wird zunächst anhand von Ergebnissen einer umfassenden Literaturrecherche ein erster Entwurf der Liste erstellt. Wie relevant der Einfluss bestimmter Medikamente auf die Gesundheit in Hitzeperioden ist, untersuchen die Forschenden außerdem anhand von routinemäßig erhobenen Gesundheitsdaten und Wetterdaten vergangener Jahre. Eine Expertenrunde erstellt in einem sogenannten Delphi-Verfahren, einem mehrstufigen Bewertungsverfahren, die finale CALOR-Liste. Über drei Monate testen eine Reihe von Ärztinnen und Ärzten, Pflegenden sowie Apotheken die Liste in der Praxis. Im Anschluss überprüft eine Expertengruppe den Einsatz der Liste und überarbeitet sie anhand der Praxiserfahrungen. Um Patientinnen und Patienten einen Zugang zu dieser Liste zu ermöglichen, werden die wesentlichen Empfehlungen in Form von Broschüren und Videoclips zusammengefasst. Das ermöglicht die Verbreitung in wichtigen Anlaufstellen des Gesundheitswesens auch in digitaler Form, beispielsweise über Social Media. Das Projekt wird für drei Jahre mit insgesamt ca. einer Million Euro gefördert.\n\nIm Erfolgsfall steht sowohl medizinischen Fachkräften als auch Patientinnen und Patienten eine gute Übersicht für eine hitzesensible Medikation mit klaren Anpassungsempfehlungen zur Verfügung.",
      "status": "laufend",
