      "acronym": "LEX LOTSEN OWL",
      "url": "https://innovationsfonds.g-ba.de/projekte/lex-lotsen-owl.576",
      "summary": "Patientenlotsen helfen Menschen mit verschiedensten Krankheitsbildern ihren Alltag gut zu bewältigen, indem Autonomie, Teilhabe und damit die Lebensqualität der Betroffenen verbessert werden.",
      "description": "Patientenlotsen helfen Menschen mit verschiedensten Krankheitsbildern ihren Alltag gut zu bewältigen, indem Autonomie, Teilhabe und damit die Lebensqualität der Betroffenen verbessert werden. Sie koordinieren unter anderem ärztliche Behandlungen oder die Medikation und unterstützen die Betroffenen in krankheits- und alltagsbezogenen administrativen Fragestellungen. In der Regel haben Lotsen einen pflegerisch-therapeutischen Berufshintergrund und nehmen direkt im Krankenhaus mit den Patientinnen und Patienten Kontakt auf. Bisher durchgeführte Projekte erprobten Machbarkeit und Effekte von Lotseninterventionen entlang verschiedener Indikationen. Wie man wirksame Verfahren in die Regelversorgung überführen und verankern kann, wurde bislang nicht ausreichend thematisiert.\n\nDas Ziel von LEX LOTSEN OWL ist, einen Pfad zur Überführung von Lotsenmodellen in die Regelversorgung zu erarbeiten. Verschiedene bestehende Lotsenprozesse wie Cardio- oder Schlaganfall-Lotsen werden in einer gemeinsamen Intervention zusammengeführt, um ein einheitliches systematisches Steuerungsverfahren zu entwickeln. Für die Umsetzung werden regional sog. Lotsenbüros aufgebaut, die die Koordination der verschiedenen Akteure sicherstellen sollen.\n\nUm die Wirksamkeit des Verfahrens und insbesondere die Arbeit der Lotsenbüros zu prüfen, wird der Zustand ohne und mit der Intervention verglichen. Das beinhaltet die Qualität des Versorgungsprozesses aus Sicht der Akteure, aber auch aus Sicht der Patientinnen und Patienten (PREMs). Zusätzlich werden organisationsspezifische Aktivitäten erfasst, welche die regionale Implementierung beeinflussen. Die Wirksamkeit und Effizienz der Organisationelemente werden analysiert und der benötigte Rechtsrahmen definiert. Das Projekt wird für vier Jahre mit insgesamt ca. 7 Millionen Euro gefördert.\n\nIm Erfolgsfall dienen die Ergebnisse der Studie als Grundlage für die notwendigen strukturellen und rechtlichen Rahmenbedingungen zur Aufnahme von Patientenlotsen in die Regelversorgung.",
      "status": "laufend",
      "states": [
        "Nordrhein-Westfalen"
      ],
